export const db_lo1 = {
  id: "db-lo1-design",
  title: "LO1: Design Database",
  description: "Conceptual data models, normalization up to 5NF, logical design, and physical design.",
  timeLimitMinutes: 30,
  questions: [
    { id: "dbl1_1", type: "multiple_choice", text: "Which model identifies entity types, relationships, and attributes to determine end-user views?", options: ["Physical Data Model", "Conceptual Data Model", "Logical Data Model", "Relational Model"], correctAnswer: 1, explanation: "A conceptual data model identifies entity types, relationships, and attributes to determine end-user views. As Dir P. T. Kunyadini describes in his textbook, a well-designed database is like a well-organized library—it caters to its users by providing the information they need in a way that's easy to access and understand. The conceptual model acts as the high-level representation of data requirements, independent of any DBMS." },
    { id: "dbl1_2", type: "multiple_choice", text: "What is an attribute domain in database design?", options: ["The server where the database is hosted", "The set of allowable values for one or more attributes", "The primary key of a table", "The relationship between two entities"], correctAnswer: 1, explanation: "A domain defines the permissible values (e.g., data type, length, constraints) for an attribute. According to Dir P. T. Kunyadini, attributes are like adjectives that describe the nouns (entities) in your data dictionary. A domain constraint restricts the valid set of values an attribute can hold to ensure data quality at the entry level." },
    { id: "dbl1_3", type: "multiple_choice", text: "Which attribute uniquely identifies each entity instance and is chosen to be the main identifier?", options: ["Candidate Key", "Alternate Key", "Foreign Key", "Primary Key"], correctAnswer: 3, explanation: "The Primary Key is the candidate key selected to uniquely identify rows in a table. As noted in the textbook, the Primary Key ('The Chosen One') is the main identifier used to uniquely reference each entity instance, establishing a parent-child relationship within the database." },
    { id: "dbl1_4", type: "multiple_choice", text: "What is an alternate key?", options: ["A candidate key that was not selected as the primary key", "A key used for backup and disaster recovery", "A foreign key in a different table", "A composite key made of three columns"], correctAnswer: 0, explanation: "Alternate keys are candidate keys that uniquely identify a row but were not chosen as the primary key. In the words of P.T. Kunyadini, alternate keys act as 'backup options,' offering extra layers of security and query flexibility when the primary key is not suitable." },
    { id: "dbl1_5", type: "multiple_choice", text: "When evaluating a DBMS for a business, which factor involves checking if it supports the required transaction volumes?", options: ["Pricing", "Scalability", "Existing Database Migration", "Color Scheme"], correctAnswer: 1, explanation: "Scalability ensures the DBMS can grow with the business's data volume and user workload. The textbook highlights that when choosing a DBMS, scalability must be analyzed through both vertical scaling (adding CPU/RAM to a server) and horizontal scaling (distributing data across multiple servers) to support transaction processing requirements." },
    { id: "dbl1_6", type: "multiple_choice", text: "What is the primary objective of database normalization?", options: ["To combine all data into one large table", "To minimize data redundancy and avoid insertion, update, and deletion anomalies", "To make SQL queries harder to write", "To increase the physical storage size"], correctAnswer: 1, explanation: "Normalization organizes data into multiple related tables to eliminate redundant data and maintain integrity. The textbook defines its three primary objectives as: 1) Reduce Data Redundancy (eliminate repetition to save space and avoid update inconsistencies), 2) Enhance Data Integrity (ensure accuracy and consistency), and 3) Simplify Data Manipulation (facilitate CRUD operations)." },
    { id: "dbl1_7", type: "multiple_choice", text: "A relation is in First Normal Form (1NF) if:", options: ["It has no foreign keys", "Every attribute contains only atomic (indivisible) values and there are no repeating groups", "It is in 3NF", "It has no partial dependencies"], correctAnswer: 1, explanation: "1NF dictates that a column cannot hold multiple values and every table must have a unique identifier (primary key). As stated in the textbook, 1NF is the foundation of normalization, eliminating duplicate rows within a single table and ensuring atomic (indivisible) values." },
    { id: "dbl1_8", type: "multiple_choice", text: "Which normal form requires the removal of partial dependencies?", options: ["1NF", "2NF", "3NF", "4NF"], correctAnswer: 1, explanation: "2NF requires that all non-key attributes are fully functionally dependent on the entire primary key, eliminating partial dependencies. The textbook notes that a partial dependency occurs when an attribute's value depends on only a part of a composite primary key, which can lead to data inconsistencies during updates." },
    { id: "dbl1_9", type: "multiple_choice", text: "What defines Third Normal Form (3NF)?", options: ["Removal of partial dependencies", "Removal of transitive dependencies", "Removal of multi-valued dependencies", "Removal of join dependencies"], correctAnswer: 1, explanation: "In 3NF, transitive dependencies must be removed. According to the textbook, a transitive dependency arises when an attribute's value depends on another non-key attribute, which in turn depends on the primary key, creating a chain of dependency that complicates data manipulation." },
    { id: "dbl1_10", type: "multiple_choice", text: "Fifth Normal Form (5NF) deals with the removal of:", options: ["Transitive dependencies", "Join dependencies where a relation cannot be decomposed without loss of data", "Partial dependencies", "Repeating groups"], correctAnswer: 1, explanation: "5NF, or Project-Join Normal Form, ensures that a table that has been decomposed can be perfectly reconstructed via joins. It eliminates join dependencies. The textbook notes that while levels beyond 3NF (like BCNF, 4NF, 5NF) exist to address highly specific scenarios, their complexity often outweighs their benefits for most applications." },
    { id: "dbl1_11", type: "multiple_choice", text: "In logical design, how is a many-to-many (M:N) binary relationship mapped?", options: ["By adding a foreign key to the larger table", "By creating a new relation (junction table) with the primary keys of both entities as foreign keys", "By combining both entities into one", "By deleting one of the entities"], correctAnswer: 1, explanation: "A junction/bridge table resolves M:N relationships into two 1:N relationships. The textbook explains that mapping many-to-many (N:M) relations requires an intersection table to link the two entities, with foreign keys referencing the primary keys of both participating tables." },
    { id: "dbl1_12", type: "multiple_choice", text: "What is a 'weak entity'?", options: ["An entity with very few attributes", "An entity that cannot be uniquely identified by its own attributes alone and depends on a strong entity", "An entity that is rarely queried", "An entity without any relationships"], correctAnswer: 1, explanation: "A weak entity uses a foreign key from its owning strong entity as part of its primary key. The textbook explains that weak entities have a 'dependent existence'—they rely on the existence of a strong (owner) entity to be identified uniquely and lack a complete primary key of their own." },
    { id: "dbl1_13", type: "multiple_choice", text: "Which integrity constraint ensures that a foreign key must match a valid primary key in the referenced table?", options: ["Domain Constraint", "Entity Integrity", "Referential Integrity", "Business Constraint"], correctAnswer: 2, explanation: "Referential integrity prevents 'orphaned' records that point to non-existent parent records. As defined by P.T. Kunyadini, referential integrity governs the relationships between tables, ensuring that a foreign key in one table references an existing, valid primary key in the parent table." },
    { id: "dbl1_14", type: "multiple_choice", text: "Entity integrity dictates that:", options: ["Foreign keys must not be null", "Primary key attributes cannot contain NULL values", "All tables must have exactly one row", "Tables must be named in plural"], correctAnswer: 1, explanation: "Entity integrity dictates that primary key attributes cannot contain NULL values. The textbook outlines that entity integrity focuses on ensuring the existence and uniqueness of identifiers within a table, preventing duplicate or empty primary key values." },
    { id: "dbl1_15", type: "multiple_choice", text: "What is a data dictionary?", options: ["A book of passwords", "A centralized repository of metadata detailing tables, attributes, domains, and constraints", "A backup of the database", "An ER diagram drawing tool"], correctAnswer: 1, explanation: "The data dictionary provides definitions and context for all database objects. The textbook defines it as a centralized repository of metadata detailing tables, attributes, domains, and constraints, which serves as a vital blueprint for communication and design validation." },
    { id: "dbl1_16", type: "multiple_choice", text: "Translating a logical data model into physical tables, specifying data types, and defining file organization is part of:", options: ["Conceptual Design", "Physical Database Design", "Requirements Gathering", "UI Design"], correctAnswer: 1, explanation: "Physical design targets a specific DBMS, mapping logical constructs to physical storage structures, data types, and file organization. The textbook notes that this step translates logical relations into database-ready structures optimized for storage and access." },
    { id: "dbl1_17", type: "multiple_choice", text: "Which file organization method stores records in the exact order they are inserted, with no specific sorting?", options: ["Indexed", "Hashed", "Heap", "Sequential"], correctAnswer: 2, explanation: "A heap file simply appends new records to the end of the file. The textbook describes Heap (unordered) file organization as a structure where records are stored in the order they are inserted with no pre-defined sequence—fast for insertions but slow for specific retrievals." },
    { id: "dbl1_18", type: "multiple_choice", text: "What does 'Hashed' file organization use to locate a record?", options: ["A binary search tree", "A mathematical algorithm (hash function) applied to a key field to determine the storage address", "A sequential scan of the entire disk", "A linked list"], correctAnswer: 1, explanation: "Hashing uses a mathematical algorithm (hash function) applied to a key field to determine the physical disk storage address. The textbook highlights that hashed access provides extremely rapid, direct O(1) retrieval for specific record lookups." },
    { id: "dbl1_19", type: "multiple_choice", text: "Why must a database administrator estimate data storage requirements?", options: ["To purchase the correct color of server chassis", "To ensure adequate disk space is provisioned for current and future data volume", "To decide the names of the tables", "To choose the font size for the database GUI"], correctAnswer: 1, explanation: "Capacity planning prevents database downtime due to disk full errors. The textbook explains that data volume analysis and capacity planning are critical to evaluate historical growth rates and determine storage and hardware requirements." },
    { id: "dbl1_20", type: "multiple_choice", text: "How is a multi-valued attribute handled in logical design?", options: ["It is ignored", "It is stored as a comma-separated string in the same table", "A new table is created containing the multi-valued attribute and a foreign key to the original entity", "It is split into exactly three columns"], correctAnswer: 2, explanation: "To maintain 1NF, multi-valued attributes become their own table linked back to the parent. The textbook specifies that mapping multi-valued attributes involves creating a separate table containing the attribute along with a foreign key referencing the primary key of the original entity." }
  ]
};

export const db_lo2 = {
  id: "db-lo2-develop",
  title: "LO2: Develop Database",
  description: "Database configuration, SQL commands (DDL, DML, DCL), testing functionality, and database security (CIA triad).",
  timeLimitMinutes: 30,
  questions: [
    { id: "dbl2_1", type: "multiple_choice", text: "What is a tablespace in database development?", options: ["A physical desk where servers sit", "A logical storage unit in a database that groups related logical structures (like tables and indexes) mapping to physical data files", "A temporary table used for calculations", "A cloud computing provider"], correctAnswer: 1, explanation: "A tablespace is a logical storage unit that groups related logical structures (like tables and indexes) mapping to physical data files. According to the textbook, tablespaces help DBAs manage disk layout and storage quotas." },
    { id: "dbl2_2", type: "multiple_choice", text: "Which SQL command is used to remove an entire tablespace from the database?", options: ["DELETE TABLESPACE", "DROP TABLESPACE", "REMOVE TABLESPACE", "TRUNCATE TABLESPACE"], correctAnswer: 1, explanation: "DROP TABLESPACE removes the logical storage unit and optionally its associated physical data files. In DDL syntax, DROP is used to delete structural objects." },
    { id: "dbl2_3", type: "multiple_choice", text: "Which set of SQL commands is used to define database structures (Create, Alter, Drop)?", options: ["Data Manipulation Language (DML)", "Data Definition Language (DDL)", "Data Control Language (DCL)", "Transaction Control Language (TCL)"], correctAnswer: 1, explanation: "Data Definition Language (DDL) defines the schema and structure of database objects, including tables, indexes, and tablespaces." },
    { id: "dbl2_4", type: "multiple_choice", text: "Which set of SQL commands is used to modify or retrieve data (Insert, Update, Delete, Select)?", options: ["DML", "DDL", "DCL", "TCL"], correctAnswer: 0, explanation: "Data Manipulation Language (DML) manages the actual data contained within the structural database objects." },
    { id: "dbl2_5", type: "multiple_choice", text: "What does the SQL command 'GRANT' do?", options: ["Creates a new table", "Assigns access rights and privileges to users or roles", "Deletes a user account", "Modifies data in a table"], correctAnswer: 1, explanation: "GRANT is a Data Control Language (DCL) command used to assign access rights and privileges to users or roles, enforcing logical database security." },
    { id: "dbl2_6", type: "multiple_choice", text: "What does the SQL command 'REVOKE' do?", options: ["Reverses a transaction", "Removes previously assigned access rights and privileges from a user", "Drops a database table", "Restarts the database server"], correctAnswer: 1, explanation: "REVOKE is a DCL command used to take away previously assigned access rights and privileges from a user." },
    { id: "dbl2_7", type: "multiple_choice", text: "In the context of database testing, what is the purpose of preparing 'test cases'?", options: ["To write the documentation", "To outline specific inputs, execution conditions, and expected results to verify functionality", "To deploy the database to production", "To estimate storage costs"], correctAnswer: 1, explanation: "Test cases outline specific inputs, execution conditions, and expected results to verify database functionality (constraints, triggers, queries) before deployment." },
    { id: "dbl2_8", type: "multiple_choice", text: "What does the 'C' stand for in the database security CIA triad?", options: ["Concurrency", "Consistency", "Confidentiality", "Clustering"], correctAnswer: 2, explanation: "Confidentiality ensures that sensitive data is accessed only by authorized individuals, preventing unauthorized data disclosure." },
    { id: "dbl2_9", type: "multiple_choice", text: "What does the 'I' stand for in the CIA triad?", options: ["Integrity", "Isolation", "Indexing", "Integration"], correctAnswer: 0, explanation: "Integrity ensures that data is accurate, complete, and not improperly modified, protecting the reliability of information." },
    { id: "dbl2_10", type: "multiple_choice", text: "What does the 'A' stand for in the CIA triad?", options: ["Atomicity", "Availability", "Authentication", "Authorization"], correctAnswer: 1, explanation: "Availability ensures that the database systems and data are accessible to authorized users when needed, minimizing downtime." },
    { id: "dbl2_11", type: "multiple_choice", text: "Which of the following is an example of 'Physical Security' for a database?", options: ["Using strong passwords", "Restricting access to the server room with biometric locks", "Encrypting network traffic", "Assigning SQL permissions"], correctAnswer: 1, explanation: "Physical security protects the actual hardware hosting the database from theft, tampering, or environmental damage, such as using biometric locks on the server room." },
    { id: "dbl2_12", type: "multiple_choice", text: "What is 'Logical Security'?", options: ["Server room cooling", "Firewalls, encryption, authentication, and SQL access rights (GRANT/REVOKE)", "Training employees not to share passwords", "Hardware backups"], correctAnswer: 1, explanation: "Logical security involves software-based access controls and network defenses, including firewalls, encryption, authentication, and SQL access privileges (GRANT/REVOKE)." },
    { id: "dbl2_13", type: "multiple_choice", text: "What does 'Behavioral Security' (or administrative security) entail?", options: ["Configuring the firewall", "Policies, user training, background checks, and enforcing an organizational security culture", "Running SQL UPDATE commands", "Locking the server rack"], correctAnswer: 1, explanation: "Behavioral security addresses the human element of security, including policies, user training, background checks, and enforcing an organizational security culture." },
    { id: "dbl2_14", type: "multiple_choice", text: "When identifying hardware requirements for a database server, which component is most critical for fast data retrieval (read performance)?", options: ["Monitor resolution", "Storage IOPS (e.g., NVMe SSDs) and RAM", "Keyboard type", "Optical Drive"], correctAnswer: 1, explanation: "Databases rely heavily on RAM for caching and fast storage IOPS (like NVMe SSDs) to retrieve and write data quickly, making these components critical for system sizing." },
    { id: "dbl2_15", type: "multiple_choice", text: "Which SQL command modifies the structure of an existing table?", options: ["UPDATE", "ALTER TABLE", "CHANGE TABLE", "MODIFY TABLE"], correctAnswer: 1, explanation: "ALTER TABLE is a DDL command used to add, drop, or modify columns and constraints on an existing table structure." },
    { id: "dbl2_16", type: "multiple_choice", text: "Which SQL command changes the values of existing data in a table?", options: ["UPDATE", "ALTER", "INSERT", "GRANT"], correctAnswer: 0, explanation: "UPDATE is a DML command used to modify existing row data based on a specified condition." },
    { id: "dbl2_17", type: "multiple_choice", text: "Why is a database security policy important?", options: ["It dictates the database pricing", "It formally outlines the rules, procedures, and responsibilities for protecting the organization's data", "It writes the SQL queries", "It designs the ERD"], correctAnswer: 1, explanation: "A security policy is the foundational document that formally outlines the rules, procedures, and responsibilities for protecting the organization's data." },
    { id: "dbl2_18", type: "multiple_choice", text: "What is SQL Injection?", options: ["A tool for importing data", "A threat where malicious SQL statements are inserted into entry fields for execution", "A backup strategy", "A database patching method"], correctAnswer: 1, explanation: "SQL Injection is a major logical security threat where malicious SQL statements are inserted into entry fields for execution, potentially bypassing authentication and stealing data." },
    { id: "dbl2_19", type: "multiple_choice", text: "Which SQL command adds a new record to a table?", options: ["CREATE", "ADD ROW", "INSERT INTO", "UPDATE"], correctAnswer: 2, explanation: "INSERT INTO is the DML command used to add new rows of data to a database table." },
    { id: "dbl2_20", type: "multiple_choice", text: "What is the purpose of testing database functionality?", options: ["To make the database look visually appealing", "To ensure queries return correct data, constraints enforce integrity, and performance meets requirements", "To increase the database size", "To generate random data"], correctAnswer: 1, explanation: "Functionality testing ensures queries return correct data, constraints enforce integrity, and performance meets transaction processing requirements before production rollout." }
  ]
};

export const db_lo3 = {
  id: "db-lo3-maintain",
  title: "LO3: Implement & Maintain Database",
  description: "Database conversion, data migration, maintaining the DBMS, and applying security patch updates.",
  timeLimitMinutes: 30,
  questions: [
    { id: "dbl3_1", type: "multiple_choice", text: "What is data migration?", options: ["Deleting old data", "The process of transferring data between storage types, formats, or computer systems", "Encrypting database tables", "Backing up the database"], correctAnswer: 1, explanation: "Data migration is the process of transferring data between storage types, formats, or computer systems, which is essential during upgrades, cloud migrations, or system consolidations." },
    { id: "dbl3_2", type: "multiple_choice", text: "Which conversion method completely switches off the old system and immediately turns on the new system?", options: ["Parallel Conversion", "Phased Conversion", "Direct (Big Bang) Conversion", "Pilot Conversion"], correctAnswer: 2, explanation: "Direct (Big Bang) conversion completely switches off the old system and immediately turns on the new system—fastest but carries the highest risk of service disruption if the new system fails." },
    { id: "dbl3_3", type: "multiple_choice", text: "Which conversion method runs both the old and new systems simultaneously for a period of time?", options: ["Direct Conversion", "Parallel Conversion", "Phased Conversion", "Pilot Conversion"], correctAnswer: 1, explanation: "Parallel conversion runs both the old and new systems simultaneously for a period of time, ensuring a safe fallback, though it is highly resource-intensive." },
    { id: "dbl3_4", type: "multiple_choice", text: "What is the main purpose of routine database maintenance?", options: ["To rewrite the database from scratch", "To ensure optimal performance, prevent data corruption, and apply security updates", "To change the database conceptual model", "To delete all user accounts"], correctAnswer: 1, explanation: "Routine database maintenance ensures optimal performance, prevents data corruption, and applies security updates, serving as the preventative care needed to avoid catastrophic failures." },
    { id: "dbl3_5", type: "multiple_choice", text: "Why is it important to communicate database maintenance windows to end users?", options: ["To ask them to do the maintenance", "To manage expectations and prevent them from attempting critical work during downtime", "To increase network speed", "To show off the DBA's workload"], correctAnswer: 1, explanation: "Communicating database maintenance windows manages user expectations and prevents data loss by scheduling downtimes during low-activity periods." },
    { id: "dbl3_6", type: "multiple_choice", text: "What is a 'patch update' in database administration?", options: ["A piece of hardware added to the server", "A software update released by the DBMS vendor to fix bugs, improve performance, or resolve security vulnerabilities", "A new table added to the schema", "A backup file"], correctAnswer: 1, explanation: "A patch update is a software update released by the DBMS vendor to fix bugs, optimize performance, or resolve critical security vulnerabilities." },
    { id: "dbl3_7", type: "multiple_choice", text: "Why must a DBA constantly check for security patch updates?", options: ["Because patches change the SQL syntax", "Because attackers constantly discover new vulnerabilities (Zero-days) in database software", "Because patches are required to use the mouse", "Because patches delete old data"], correctAnswer: 1, explanation: "DBAs must constantly check for security patches because attackers continuously discover new exploits (zero-day vulnerabilities) targeting database software." },
    { id: "dbl3_8", type: "multiple_choice", text: "Before applying a major DBMS patch to a production environment, what should the DBA do?", options: ["Turn off the server", "Test the patch in a staging or development environment first", "Delete the production data", "Change the database name"], correctAnswer: 1, explanation: "Before applying any major DBMS patch to production, the DBA must test the patch in a staging or development environment to ensure compatibility." },
    { id: "dbl3_9", type: "multiple_choice", text: "What is index rebuilding/reorganization during maintenance?", options: ["Re-typing the data dictionary", "Defragmenting indexes to improve query read performance", "Changing primary keys to foreign keys", "Creating new users"], correctAnswer: 1, explanation: "Index rebuilding or reorganizing defragments indexes to improve read performance, restoring query speeds that naturally degrade as records are updated." },
    { id: "dbl3_10", type: "multiple_choice", text: "What is 'Database Training' in the context of system conversion?", options: ["Training the AI model", "Educating users and staff on how to use the new database system, front-end tools, and procedures", "Exercising the database server", "Running benchmark tests"], correctAnswer: 1, explanation: "Database training involves educating users and IT staff on how to use the new database system, interfaces, and protocols, which is vital for system adoption." },
    { id: "dbl3_11", type: "multiple_choice", text: "What is a Phased Conversion?", options: ["Replacing the entire system at once", "Implementing the new system in modules or stages over time", "Running two identical systems forever", "Installing the system in one branch only"], correctAnswer: 1, explanation: "Phased conversion implements the new system in modules or stages over time, reducing risk by scaling the rollout gradually." },
    { id: "dbl3_12", type: "multiple_choice", text: "What is a Pilot Conversion?", options: ["Using airplanes to move servers", "Deploying the full new system to a single department or branch first as a test, before a full rollout", "Running old and new systems together", "Migrating data overnight"], correctAnswer: 1, explanation: "Pilot conversion deploys the full new system to a single department or branch first as a live test, verifying stability before a full enterprise rollout." },
    { id: "dbl3_13", type: "multiple_choice", text: "When updating a DBMS, why is it necessary to 'plan for appropriate resources'?", options: ["To buy more desks", "To ensure enough disk space, memory, CPU, and downtime are available for the upgrade process", "To hire more programmers", "To change the company logo"], correctAnswer: 1, explanation: "Planning for upgrades requires allocating appropriate hardware and downtime resources to ensure sufficient memory, CPU, and disk space are available for data reorganization." },
    { id: "dbl3_14", type: "multiple_choice", text: "What does 'updating database security periodically' involve?", options: ["Changing the database color theme", "Reviewing user permissions (removing inactive users), rotating passwords, and applying security patches", "Deleting all audit logs", "Changing the primary keys"], correctAnswer: 1, explanation: "Updating database security periodically involves auditing access rights (revoking unnecessary roles), rotating administrative passwords, and checking patch status." },
    { id: "dbl3_15", type: "multiple_choice", text: "Which supporting software might need to be reconnected/reconfigured after a DBMS update?", options: ["Only the operating system", "Application servers, web servers, reporting tools, and backup agents", "Word processors", "Web browsers"], correctAnswer: 1, explanation: "After a major DBMS update, downstream systems like application servers, reporting tools, web servers, and backup agents may need reconfiguration." },
    { id: "dbl3_16", type: "multiple_choice", text: "What is the primary risk of NOT performing routine database maintenance?", options: ["The database will automatically delete itself", "Performance will severely degrade over time, and the risk of catastrophic failure increases", "The SQL language will stop working", "The database will upgrade itself incorrectly"], correctAnswer: 1, explanation: "Neglecting routine database maintenance leads to severe query performance degradation, increased risk of data corruption, and catastrophic system failures." },
    { id: "dbl3_17", type: "multiple_choice", text: "Which maintenance task reclaims physical disk space left by deleted records?", options: ["Vacuuming / Shrinking", "Indexing", "Normalization", "Hashing"], correctAnswer: 0, explanation: "Vacuuming (PostgreSQL) or shrinking (SQL Server) reclaims unused physical storage space left by deleted records, keeping files compact and optimized." },
    { id: "dbl3_18", type: "multiple_choice", text: "What is an ETL tool in the context of data migration?", options: ["Extra Time Logic", "Extract, Transform, Load - tools used to pull data from the old system, format it, and insert it into the new system", "Electronic Table List", "Encrypted Transfer Layer"], correctAnswer: 1, explanation: "ETL (Extract, Transform, Load) tools are critical during data migration to extract data from legacy systems, clean and reformat it, and load it into the new schema." },
    { id: "dbl3_19", type: "multiple_choice", text: "If a security patch breaks a critical application query, what should the DBA do?", options: ["Tell users to stop using the application", "Roll back the patch (using the backup taken prior to patching) and work with the vendor/developers for a fix", "Delete the database", "Ignore the complaints"], correctAnswer: 1, explanation: "If a patch breaks a production query, the DBA must roll back the system using the pre-patch backup and coordinate a fix with developers." },
    { id: "dbl3_20", type: "multiple_choice", text: "What is the purpose of database statistics updating during maintenance?", options: ["To count how many users logged in", "To provide the query optimizer with current data distribution metrics so it can generate efficient execution plans", "To calculate the DBA's salary", "To estimate internet speed"], correctAnswer: 1, explanation: "Updating database statistics provides the query optimizer with accurate data distribution metrics, ensuring it continues to choose efficient query paths." }
  ]
};

export const db_lo4 = {
  id: "db-lo4-backup",
  title: "LO4: Backup & Disaster Recovery",
  description: "RTO, RPO, backup scheduling, media selection, mirroring, log-based recovery, and shadow paging.",
  timeLimitMinutes: 30,
  questions: [
    { id: "dbl4_1", type: "multiple_choice", text: "What does Recovery Time Objective (RTO) measure?", options: ["The amount of data lost", "The maximum acceptable amount of time the database can be offline before the business suffers unacceptable consequences", "The cost of the backup media", "The time it takes to install the DBMS"], correctAnswer: 1, explanation: "Recovery Time Objective (RTO) measures the maximum acceptable downtime the business can tolerate before suffering major consequences." },
    { id: "dbl4_2", type: "multiple_choice", text: "What does Recovery Point Objective (RPO) measure?", options: ["The maximum acceptable amount of data loss, measured in time (e.g., losing the last 15 minutes of data)", "The physical location of the backup server", "The number of users currently online", "The time taken to run a full backup"], correctAnswer: 0, explanation: "Recovery Point Objective (RPO) measures the maximum acceptable data loss, expressed in time (e.g., losing no more than the last 15 minutes of transactions)." },
    { id: "dbl4_3", type: "multiple_choice", text: "What is a 'Full Backup'?", options: ["A backup of only the transaction logs", "A complete copy of the entire database structure and all data at a specific point in time", "A backup of data that changed since yesterday", "A backup stored on a full disk"], correctAnswer: 1, explanation: "A full backup is a complete copy of the entire database structure and all data at a specific point in time, serving as the baseline for other backups." },
    { id: "dbl4_4", type: "multiple_choice", text: "What is a 'Differential Backup'?", options: ["A backup of all data", "A backup of all changes made since the last FULL backup", "A backup of only the database schema", "A backup of changes made since the last incremental backup"], correctAnswer: 1, explanation: "A differential backup captures only the changes made since the last FULL backup, making restores faster since you only need the full and the latest differential." },
    { id: "dbl4_5", type: "multiple_choice", text: "What is an 'Incremental Backup'?", options: ["A backup of all changes made since ANY last backup (full or incremental)", "A backup of changes made since the last full backup", "A complete database copy", "A printed copy of the data"], correctAnswer: 0, explanation: "An incremental backup captures changes made since the last backup of ANY type (full or incremental), offering fast backup times but a slower restore sequence." },
    { id: "dbl4_6", type: "multiple_choice", text: "Which factor heavily influences the choice of backup medium (e.g., Tape vs. Cloud vs. SSD)?", options: ["The color of the server", "Cost, required read/write speed, and off-site storage requirements", "The SQL commands used", "The number of primary keys"], correctAnswer: 1, explanation: "Selecting backup media (Tape vs. Cloud vs. SSD) involves balancing storage costs, required restore speeds, and regulatory off-site requirements." },
    { id: "dbl4_7", type: "multiple_choice", text: "What is Database Mirroring?", options: ["Reflecting the server screen", "Maintaining an exact, real-time copy of the database on a separate standby server for high availability", "Copying the database to a tape drive", "Encrypting the database"], correctAnswer: 1, explanation: "Database mirroring maintains a redundant, real-time copy of the active database on a standby server to achieve high availability and low RTO." },
    { id: "dbl4_8", type: "multiple_choice", text: "What is 'Log-based Recovery'?", options: ["Reading a text file to manually re-type data", "Using the transaction log files to REDO committed transactions and UNDO uncommitted transactions after a crash", "Backing up only wooden logs", "Using an external reporting tool"], correctAnswer: 1, explanation: "Log-based recovery uses transaction log files to replay (REDO) committed transactions and roll back (UNDO) uncommitted ones during crash recovery." },
    { id: "dbl4_9", type: "multiple_choice", text: "What is a 'Checkpoint' in database recovery?", options: ["A physical security guard at the server room", "A point in time where the DBMS flushes all modified data from RAM memory to physical disk, shortening recovery time", "A tool to check for viruses", "A type of database index"], correctAnswer: 1, explanation: "A checkpoint is a point in time where the DBMS flushes dirty pages in memory to physical disk, significantly shortening crash recovery times." },
    { id: "dbl4_10", type: "multiple_choice", text: "What is the 'Shadow Paging' recovery technique?", options: ["Hiding pages from users", "Creating a copy (shadow) of the database pages being modified. If the transaction commits, the shadow becomes the live page; if it fails, the shadow is discarded.", "Printing the database on dark paper", "Using a secondary monitor"], correctAnswer: 1, explanation: "Shadow paging is a crash recovery technique where modified pages are written to a duplicate (shadow) directory, ensuring atomic updates without undo logs." },
    { id: "dbl4_11", type: "multiple_choice", text: "What is a Disaster Recovery Plan (DRP)?", options: ["A plan to cause a disaster", "A documented, structured approach describing how to restore operations and data after a catastrophic event", "A plan to upgrade the RAM", "A SQL script to create tables"], correctAnswer: 1, explanation: "A Disaster Recovery Plan (DRP) is a documented, structured approach describing technical procedures, roles, and contacts to restore operations after a catastrophe." },
    { id: "dbl4_12", type: "multiple_choice", text: "Why is 'off-site storage' critical for backups?", options: ["To save local disk space", "To protect the data against physical disasters (fire, flood, theft) that might destroy the primary data center", "To make it harder for the DBA to find", "To improve query performance"], correctAnswer: 1, explanation: "Off-site storage protects backups from physical site disasters (fire, flood, theft) that could destroy both the live database and local backup files." },
    { id: "dbl4_13", type: "multiple_choice", text: "Which type of failure occurs when the disk drive containing the database physically breaks?", options: ["Transaction failure", "System crash", "Media failure", "Network failure"], correctAnswer: 2, explanation: "Media failure refers to the physical breakdown of storage drives containing the database, which requires restoring data from backup files." },
    { id: "dbl4_14", type: "multiple_choice", text: "What is a 'System Crash' failure?", options: ["A hard drive melting", "A hardware or OS failure (like power loss or kernel panic) where RAM is lost but disks remain intact", "A user typing a wrong password", "A dropped network packet"], correctAnswer: 1, explanation: "A system crash is a hardware or OS failure where volatile memory (RAM) is lost but non-volatile disks remain intact, allowing quick recovery using log files." },
    { id: "dbl4_15", type: "multiple_choice", text: "What does the acronym 'SAN' stand for in backup storage?", options: ["System Area Network", "Storage Area Network - a dedicated high-speed network that provides access to consolidated block-level storage", "Standard Access Node", "Simple Array Network"], correctAnswer: 1, explanation: "A Storage Area Network (SAN) is a dedicated high-speed network that provides consolidated block-level storage, heavily used in enterprise database systems." },
    { id: "dbl4_16", type: "multiple_choice", text: "Why should backup restoration be tested regularly?", options: ["To use up excess electricity", "To verify that the backup files are not corrupt and that the team knows the RTO can be met", "To delete the backups", "To format the database"], correctAnswer: 1, explanation: "Regularly testing backup restoration is essential to verify that backup files are not corrupt and that the disaster recovery team can meet the business RTO." },
    { id: "dbl4_17", type: "multiple_choice", text: "What is 'Point-in-Time Recovery'?", options: ["Recovering data right on time", "Restoring a database, and then applying transaction logs to stop at a specific minute/second before a disaster or user error occurred", "A physical clock synchronization", "Restoring only one table"], correctAnswer: 1, explanation: "Point-in-Time Recovery (PITR) allows a DBA to restore a database to a specific minute or second, which is vital for reversing accidental data deletions." },
    { id: "dbl4_18", type: "multiple_choice", text: "In a highly transactional system (e.g., banking), what should the RPO be?", options: ["24 hours", "1 week", "As close to zero as possible (e.g., synchronous mirroring)", "1 month"], correctAnswer: 2, explanation: "Highly transactional systems like banking require an RPO as close to zero as possible, which is achieved using synchronous mirroring or active replication." },
    { id: "dbl4_19", type: "multiple_choice", text: "What is a transaction log backup?", options: ["Backing up the Windows Event Viewer", "Backing up only the transaction log file, which truncates the log and frees up space while allowing point-in-time recovery", "A full copy of the database", "A list of user logins"], correctAnswer: 1, explanation: "Transaction log backups back up the active log file, which truncates the log to free up disk space while enabling continuous point-in-time recovery." },
    { id: "dbl4_20", type: "multiple_choice", text: "What is the 3-2-1 backup rule?", options: ["3 backups, 2 servers, 1 DBA", "3 copies of data, on 2 different media types, with 1 copy off-site", "3 databases, 2 tables, 1 row", "3 hours to backup, 2 hours to restore, 1 hour to test"], correctAnswer: 1, explanation: "The 3-2-1 backup rule specifies maintaining 3 copies of data, stored on 2 different media types, with at least 1 copy kept off-site." }
  ]
};

export const db_lo5 = {
  id: "db-lo5-concurrency",
  title: "LO5: Transaction & Concurrency",
  description: "ACID properties, concurrency problems (Lost update, etc), 2PL, Timestamping, and Deadlock management.",
  timeLimitMinutes: 30,
  questions: [
    { id: "dbl5_1", type: "multiple_choice", text: "What is a database transaction?", options: ["A network ping", "A logical unit of work consisting of one or more SQL statements that must succeed or fail together", "A money transfer over the internet", "A single row in a table"], correctAnswer: 1, explanation: "A transaction is a logical unit of work consisting of one or more SQL statements that must succeed or fail together as a single atomic operation." },
    { id: "dbl5_2", type: "multiple_choice", text: "What does the 'Atomicity' property of ACID guarantee?", options: ["Data is always available", "Transactions execute extremely fast", "A transaction is 'all or nothing'—if any part fails, the entire transaction is rolled back", "Only authorized users can access the database"], correctAnswer: 2, explanation: "Atomicity guarantees that a transaction is 'all-or-nothing'—if any statement fails, the entire transaction is rolled back, preventing partial updates." },
    { id: "dbl5_3", type: "multiple_choice", text: "What does the 'Consistency' property of ACID guarantee?", options: ["The database uses consistent naming conventions", "A transaction must transform the database from one valid state to another valid state, maintaining all constraints and rules", "The server stays on constantly", "Backups are consistent"], correctAnswer: 1, explanation: "Consistency guarantees that a transaction must transition the database from one valid state to another, maintaining all integrity constraints and business rules." },
    { id: "dbl5_4", type: "multiple_choice", text: "What does the 'Isolation' property of ACID guarantee?", options: ["The database is physically isolated from the internet", "Concurrent transactions execute independently, and their intermediate states are invisible to other transactions", "Transactions are stored on isolated disks", "Users must work alone"], correctAnswer: 1, explanation: "Isolation guarantees that concurrent transactions execute independently without interference, making their intermediate states invisible to other transactions." },
    { id: "dbl5_5", type: "multiple_choice", text: "What does the 'Durability' property of ACID guarantee?", options: ["The server hardware is physically durable", "The database engine will not crash", "Once a transaction is committed, its changes are permanent and will survive a subsequent system failure", "Tables can hold durable data types"], correctAnswer: 2, explanation: "Durability guarantees that once a transaction is committed, its updates are permanent and will survive any subsequent system or power failures." },
    { id: "dbl5_6", type: "multiple_choice", text: "What is the 'Lost Update' concurrency problem?", options: ["A file gets deleted accidentally", "Two transactions read the same data, modify it, and write it back, causing one transaction to overwrite and lose the other's changes", "A query fails to find a record", "A backup is lost"], correctAnswer: 1, explanation: "The Lost Update problem occurs when two concurrent transactions read the same record, modify it, and write it back, causing one update to overwrite the other." },
    { id: "dbl5_7", type: "multiple_choice", text: "What is the 'Uncommitted Dependency' (Dirty Read) concurrency problem?", options: ["A table depends on a deleted table", "A transaction reads data that has been modified by another transaction that has not yet committed; if the other transaction rolls back, the data is invalid", "A user forgets to log out", "A script contains a dirty bug"], correctAnswer: 1, explanation: "An Uncommitted Dependency (Dirty Read) occurs when a transaction reads data modified by another transaction that has not yet committed; if the other rolls back, the data becomes invalid." },
    { id: "dbl5_8", type: "multiple_choice", text: "What is the 'Inconsistent Retrievals' (Non-repeatable Read) problem?", options: ["The database crashes during a read", "A transaction reads the same row twice, but gets different values because another transaction modified it in between", "A query returns data in a random order", "The network drops packets"], correctAnswer: 1, explanation: "Inconsistent Retrievals (Non-repeatable Read) occur when a transaction reads a row twice but gets different values because another transaction modified it in between." },
    { id: "dbl5_9", type: "multiple_choice", text: "Which protocol is the standard approach to managing concurrency in relational databases?", options: ["HTTP Protocol", "Two-Phase Locking (2PL) Protocol", "File Transfer Protocol (FTP)", "Simple Mail Transfer Protocol (SMTP)"], correctAnswer: 1, explanation: "Two-Phase Locking (2PL) is a standard protocol comprising a Growing Phase (acquiring locks) and a Shrinking Phase (releasing locks) to ensure serializability." },
    { id: "dbl5_10", type: "multiple_choice", text: "In database locking, what is an 'Exclusive Lock' (Write Lock)?", options: ["A lock that allows anyone to read", "A lock that grants a single transaction exclusive access to modify data, preventing other transactions from reading or writing it", "A lock for administrators only", "A physical lock on the server rack"], correctAnswer: 1, explanation: "An Exclusive Lock (Write Lock) grants a single transaction exclusive access to modify data, preventing any other concurrent transactions from reading or writing it." },
    { id: "dbl5_11", type: "multiple_choice", text: "What is a 'Shared Lock' (Read Lock)?", options: ["A lock that prevents reading", "A lock that allows multiple transactions to read the same data simultaneously, but prevents anyone from writing/modifying it", "A lock that deletes data", "A social media share button"], correctAnswer: 1, explanation: "A Shared Lock (Read Lock) allows multiple concurrent transactions to read the same data, but blocks any transaction from writing or modifying it." },
    { id: "dbl5_12", type: "multiple_choice", text: "What is 'Deadlock'?", options: ["When the server dies", "A situation where Transaction A holds a lock needed by Transaction B, and Transaction B holds a lock needed by Transaction A, causing an infinite wait", "When a lock key is lost", "When a hard drive stops spinning"], correctAnswer: 1, explanation: "A Deadlock is a circular wait condition where Transaction A holds a lock needed by B, and B holds a lock needed by A, causing both to wait indefinitely." },
    { id: "dbl5_13", type: "multiple_choice", text: "How does a DBMS typically handle a deadlock?", options: ["It turns off the server", "It detects the cycle and aborts/rolls back one of the transactions (the victim) to free its locks", "It asks the users to decide", "It deletes the locked data"], correctAnswer: 1, explanation: "The DBMS typically resolves a deadlock by running a detection cycle, identifying the circular dependency, and aborting/rolling back one transaction (the victim)." },
    { id: "dbl5_14", type: "multiple_choice", text: "What is 'Starvation' in concurrency control?", options: ["The database runs out of RAM", "A situation where a transaction is perpetually denied the locks it needs because other transactions keep jumping ahead of it", "The network has no bandwidth", "A power outage"], correctAnswer: 1, explanation: "Starvation occurs when a transaction is perpetually denied the locks it needs because other transactions keep jumping ahead in the lock queue." },
    { id: "dbl5_15", type: "multiple_choice", text: "What is the difference between Deadlock and Starvation?", options: ["They are the same thing", "Deadlock is a circular wait affecting multiple blocked transactions; Starvation is a single transaction waiting forever while others continue processing", "Deadlock is a hardware issue; Starvation is a software issue", "Starvation only happens in NoSQL"], correctAnswer: 1, explanation: "Deadlock involves a circular wait between multiple blocked transactions; Starvation is a single transaction waiting indefinitely while other active transactions proceed." },
    { id: "dbl5_16", type: "multiple_choice", text: "What is the 'Time-stamp based protocol' for concurrency?", options: ["Using a calendar to schedule queries", "Assigning a unique timestamp to each transaction to decide the order of execution and resolve conflicts without using locks", "Recording when users log in", "Using network time protocol (NTP)"], correctAnswer: 1, explanation: "Timestamp-based protocols assign a unique, monotonically increasing timestamp to transactions, ordering execution and resolving conflicts without locking." },
    { id: "dbl5_17", type: "multiple_choice", text: "What is the 'Validation-based protocol' (Optimistic Concurrency Control)?", options: ["Asking a manager for permission", "Assuming conflicts are rare, transactions modify private copies of data and only check for conflicts right before committing", "Checking passwords multiple times", "Using checksums on files"], correctAnswer: 1, explanation: "Validation-based protocols (Optimistic Concurrency Control) assume conflicts are rare, allowing transactions to update local copies and only checking for conflicts at commit time." },
    { id: "dbl5_18", type: "multiple_choice", text: "In a transaction state diagram, what state comes after a successful 'Active' and 'Partially Committed' execution?", options: ["Failed", "Aborted", "Committed", "Suspended"], correctAnswer: 2, explanation: "In a transaction state diagram, after a transaction successfully executes its last statement, it enters the 'Partially Committed' state before committing permanently." },
    { id: "dbl5_19", type: "multiple_choice", text: "If a transaction violates a constraint during execution, into which state does it transition?", options: ["Committed", "Failed (and subsequently Aborted)", "Active", "Complete"], correctAnswer: 1, explanation: "If a transaction violates a constraint or encounters an error, it transitions to the 'Failed' state, subsequently moving to 'Aborted' after a rollback." },
    { id: "dbl5_20", type: "multiple_choice", text: "Why is concurrency control strictly necessary in a multi-user database?", options: ["To make the database look modern", "To ensure that concurrent operations interleave in a way that preserves data consistency and ACID properties", "To limit the number of users", "To force users to type queries slowly"], correctAnswer: 1, explanation: "Concurrency control is strictly necessary in multi-user databases to interleave concurrent operations in a way that preserves data consistency and ACID properties." }
  ]
};
